#include <iostream>
#include <vector>
#include <map>
using namespace std;

struct Node{
  int val, par;
  vector<int> vec;
  Node(int v, int p){val = v, par = p;};
};

int Q;
map<int, int> mp;
vector<Node> vec;

int main(void)
{
  ios::sync_with_stdio(0);
  cin.tie(0);
  cin >> Q;

  int v = 0;
  vec.push_back(Node(-1, 0));

  string s; int x;
  for(int i = 1; i <= Q; i++){
    cin >> s;
    if(s == "ADD"){
      cin >> x;
      vec.push_back(Node(x, v));
      vec[v].vec.push_back((int)vec.size()-1);
      v = (int)vec.size()-1;
    }
    if(s == "DELETE") v = vec[v].par;
    if(s == "SAVE"){
      cin >> x;
      mp[x] = v;
    }
    if(s == "LOAD"){
      cin >> x;
      v = mp[x];
    }
    cout << vec[v].val << " ";
  }
  cout << endl;

  return 0;
}

#include <bits/extc++.h>

struct linked_list {
  struct node {
    int val;
    node* next;
    node(int val, node* next) : val(val), next(next) {}
  };

  node* head;

  linked_list() : head(nullptr) {}

  void push(int val) { head = new node(val, head); }

  void pop() {
    if (head) {
      head = head->next;
    }
  }

  int get() {
    if (head) {
      return head->val;
    } else {
      return -1;
    }
  }
};

int main() {
  int q;
  std::cin >> q;

  std::map<int, linked_list> notebook;

  linked_list a;

  for (int i = 0; i < q; ++i) {
    std::string op;
    std::cin >> op;

    if (op == "ADD") {
      int x;
      std::cin >> x;

      a.push(x);
    } else if (op == "DELETE") {
      a.pop();
    } else if (op == "SAVE") {
      int y;
      std::cin >> y;

      notebook[y] = a;
    } else if (op == "LOAD") {
      int z;
      std::cin >> z;

      a = notebook[z];
    }

    std::cout << a.get() << (i == q - 1 ? '\n' : ' ');
  }
}
